/// The table of `maker`'s main directory (`list` 0), or of the list under
/// its tag `list`.
pub(crate) fn table(maker: &str, list: u16) -> Option<&'static [Tag]> {
    Some(match (maker, list) {
        ("APPLE", 0x0000) => APPLE,
        ("CANON", 0x0000) => CANON,
        ("CANON", 0x0001) => CANON_CAMERA_SETTINGS,
        ("CANON", 0x0002) => CANON_FOCAL_LENGTH,
        ("CANON", 0x0004) => CANON_SHOT_INFO,
        ("CANON", 0x0012) => CANON_AF_INFO,
        ("CANON", 0x0093) => CANON_FILE_INFO,
        ("CASIO", 0x0000) => CASIO,
        ("DJI", 0x0000) => DJI,
        ("FUJIFILM", 0x0000) => FUJIFILM,
        ("NIKON", 0x0000) => NIKON,
        ("OLYMPUS", 0x0000) => OLYMPUS,
        ("SONY", 0x0000) => SONY,
        _ => return None,
    })
}
